    },
    {
      "issue_id": "SPA-N-003",
      "position": "PUSHBACK",
      "evidence": "General warranties: negotiate a higher cap, lower thresholds and a longer period where needed."
    },
    {
      "issue_id": "SPA-N-004",
      "position": "PUSHBACK",
      "evidence": "Title and capacity: a cap at least equal to the purchase price and a substantially longer limitation period appropriate to the claim"
    },
    {
      "issue_id": "SPA-N-005",
      "position": "PUSHBACK",
      "evidence": "Express carve-outs, to the extent legally permissible, for fraud and other deliberate misconduct."
    },
    {
      "issue_id": "SPA-N-006",
      "position": "PUSHBACK",
      "evidence": "Reject blanket data-room and public-register disclosure."
    },
    {
      "issue_id": "SPA-N-007",
      "position": "PUSHBACK",
      "evidence": "Reject constructive knowledge and matters merely “discoverable”."
    },
    {
      "issue_id": "SPA-N-008",
      "position": "PUSHBACK",
      "evidence": "Require effective Bluefen consent and satisfaction of its conditions"
    },
    {
      "issue_id": "SPA-N-009",
      "position": "PUSHBACK",
      "evidence": "repay Riverlark and secure releases at Completion."
    },
    {
      "issue_id": "SPA-N-010",
      "position": "PUSHBACK",
      "evidence": "Seller funding or a dollar-for-dollar purchase-price adjustment for bonuses triggered by the transaction, including applicable on-costs"
    },
    {
      "issue_id": "SPA-N-011",
      "position": "PUSHBACK",
      "evidence": "Expand the specific indemnity to cover losses arising from the payment condition, ownership or use of the relevant IP and related claims and remediation"
    },
    {
      "issue_id": "SPA-N-012",
      "position": "PUSHBACK",
      "evidence": "Seek a specific indemnity for incident-related losses and reasonable investigation, notification and remediation costs, with express treatment outside the general warranty limitations."
    },
    {
      "issue_id": "SPA-N-013",
      "position": "PARTIAL",
      "evidence": "Allocate any pre-Completion accrual or transaction-related commitment consistently with the working-capital and debt-like-item mechanics, avoiding double counting."
    },
    {
      "issue_id": "SPA-N-014",
      "position": "PUSHBACK",
      "evidence": "Reject application of general warranty limits to every claim"
    },
    {
      "issue_id": "SPA-N-015",
      "position": "PUSHBACK",
      "evidence": "Obtain and check the current register and corporate records, share capital and issuance history, encumbrances and any options or rights to acquire shares"
    },
    {
      "issue_id": "SPA-N-016",
      "position": "PUSHBACK",
      "evidence": "IP warranties also need substantive review and a suitable limitation period and cap"
    }
  ],
